    "\u7279\u6b8a\u7684\u4e8c\u8fdb\u5236\u5b57\u7b26\u4e32 \u662f\u5177\u6709\u4ee5\u4e0b\u4e24\u4e2a\u6027\u8d28\u7684\u4e8c\u8fdb\u5236\u5e8f\u5217\uff1a\n\n\t0 \u7684\u6570\u91cf\u4e0e 1 \u7684\u6570\u91cf\u76f8\u7b49\u3002\n\n\t\u4e8c\u8fdb\u5236\u5e8f\u5217\u7684\u6bcf\u4e00\u4e2a\u524d\u7f00\u7801\u4e2d 1 \u7684\u6570\u91cf\u8981\u5927\u4e8e\u7b49\u4e8e 0 \u7684\u6570\u91cf\u3002\n\n\u7ed9\u5b9a\u4e00\u4e2a\u7279\u6b8a\u7684\u4e8c\u8fdb\u5236\u5b57\u7b26\u4e32\u00a0s\u3002\n\n\u4e00\u6b21\u79fb\u52a8\u64cd\u4f5c\u5305\u62ec\u9009\u62e9\u5b57\u7b26\u4e32 s \u4e2d\u7684\u4e24\u4e2a\u8fde\u7eed\u7684\u3001\u975e\u7a7a\u7684\u3001\u7279\u6b8a\u5b50\u4e32\uff0c\u5e76\u4ea4\u6362\u5b83\u4eec\u3002\u4e24\u4e2a\u5b57\u7b26\u4e32\u662f\u8fde\u7eed\u7684\uff0c\u5982\u679c\u7b2c\u4e00\u4e2a\u5b57\u7b26\u4e32\u7684\u6700\u540e\u4e00\u4e2a\u5b57\u7b26\u4e0e\u7b2c\u4e8c\u4e2a\u5b57\u7b26\u4e32\u7684\u7b2c\u4e00\u4e2a\u5b57\u7b26\u7684\u7d22\u5f15\u76f8\u5dee\u6b63\u597d\u4e3a 1\u3002\n\n\u8fd4\u56de\u5728\u5b57\u7b26\u4e32\u4e0a\u5e94\u7528\u4efb\u610f\u6b21\u64cd\u4f5c\u540e\u53ef\u80fd\u5f97\u5230\u7684\u5b57\u5178\u5e8f\u6700\u5927\u7684\u5b57\u7b26\u4e32\u3002\n\n\u00a0\n\n\u793a\u4f8b 1:\n\n```\n\u8f93\u5165: S = \"11011000\"\n\u8f93\u51fa: \"11100100\"\n\u89e3\u91ca:\n\u5c06\u5b50\u4e32 \"10\" \uff08\u5728 s[1] \u51fa\u73b0\uff09 \u548c \"1100\" \uff08\u5728 s[3] \u51fa\u73b0\uff09\u8fdb\u884c\u4ea4\u6362\u3002\n\u8fd9\u662f\u5728\u8fdb\u884c\u82e5\u5e72\u6b21\u64cd\u4f5c\u540e\u6309\u5b57\u5178\u5e8f\u6392\u5217\u6700\u5927\u7684\u7ed3\u679c\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1as = \"10\"\n\u8f93\u51fa\uff1a\"10\"\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= s.length <= 50\n\n\ts[i]\u00a0\u4e3a\u00a0'0' \u6216\u00a0'1'\u3002\n\n\ts\u00a0\u662f\u4e00\u4e2a\u7279\u6b8a\u7684\u4e8c\u8fdb\u5236\u5b57\u7b26\u4e32\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1as\u3002",
    "\u8f93\u51fa string \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def makeLargestSpecial(self, s: str) -> str:\n        if len(s) <= 2:\n            return s\n        \n        cnt = left = 0\n        subs = list()\n\n        for i, ch in enumerate(s):\n            if ch == \"1\":\n                cnt += 1\n            else:\n                cnt -= 1\n                if cnt == 0:\n                    subs.append(\"1\" + self.makeLargestSpecial(s[left+1:i]) + \"0\")\n                    left = i + 1\n        \n        subs.sort(reverse=True)\n        return \"\".join(subs)\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.makeLargestSpecial(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
