    "\u7ed9\u5b9a\u4e00\u4e2a\u5b57\u7b26\u4e32 s \u548c\u4e00\u4e2a\u6574\u6570 k\u00a0\u3002\u4f60\u53ef\u4ee5\u4ece s \u7684\u524d k \u4e2a\u5b57\u6bcd\u4e2d\u9009\u62e9\u4e00\u4e2a\uff0c\u5e76\u628a\u5b83\u52a0\u5230\u5b57\u7b26\u4e32\u7684\u672b\u5c3e\u3002\n\n\u8fd4\u56de \u5728\u5e94\u7528\u4e0a\u8ff0\u6b65\u9aa4\u7684\u4efb\u610f\u6570\u91cf\u7684\u79fb\u52a8\u540e\uff0c\u5b57\u5178\u5e8f\u6700\u5c0f\u7684\u5b57\u7b26\u4e32\u00a0\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1as = \"cba\", k = 1\n\u8f93\u51fa\uff1a\"acb\"\n\u89e3\u91ca\uff1a\n\u5728\u7b2c\u4e00\u6b65\u4e2d\uff0c\u6211\u4eec\u5c06\u7b2c\u4e00\u4e2a\u5b57\u7b26\uff08\u201cc\u201d\uff09\u79fb\u52a8\u5230\u6700\u540e\uff0c\u83b7\u5f97\u5b57\u7b26\u4e32 \u201cbac\u201d\u3002\n\u5728\u7b2c\u4e8c\u6b65\u4e2d\uff0c\u6211\u4eec\u5c06\u7b2c\u4e00\u4e2a\u5b57\u7b26\uff08\u201cb\u201d\uff09\u79fb\u52a8\u5230\u6700\u540e\uff0c\u83b7\u5f97\u6700\u7ec8\u7ed3\u679c \u201cacb\u201d\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1as = \"baaca\", k = 3\n\u8f93\u51fa\uff1a\"aaabc\"\n\u89e3\u91ca\uff1a\n\u5728\u7b2c\u4e00\u6b65\u4e2d\uff0c\u6211\u4eec\u5c06\u7b2c\u4e00\u4e2a\u5b57\u7b26\uff08\u201cb\u201d\uff09\u79fb\u52a8\u5230\u6700\u540e\uff0c\u83b7\u5f97\u5b57\u7b26\u4e32 \u201caacab\u201d\u3002\n\u5728\u7b2c\u4e8c\u6b65\u4e2d\uff0c\u6211\u4eec\u5c06\u7b2c\u4e09\u4e2a\u5b57\u7b26\uff08\u201cc\u201d\uff09\u79fb\u52a8\u5230\u6700\u540e\uff0c\u83b7\u5f97\u6700\u7ec8\u7ed3\u679c \u201caaabc\u201d\u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= k\u00a0<= s.length\u00a0<= 1000\n\n\ts\u00a0\u53ea\u7531\u5c0f\u5199\u5b57\u6bcd\u7ec4\u6210\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1as\u3001k\u3002",
    "\u8f93\u51fa string \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def orderlyQueue(self, s: str, k: int) -> str:\n        if k == 1:\n            ans = s\n            for _ in range(len(s) - 1):\n                s = s[1:] + s[0]\n                ans = min(ans, s)\n            return ans\n        return ''.join(sorted(s))\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.orderlyQueue(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "str",
