    "\u7ed9\u5b9a\u4e00\u4e2a\u5355\u8bcd\u6570\u7ec4\u00a0words \u548c\u4e00\u4e2a\u957f\u5ea6\u00a0maxWidth\u00a0\uff0c\u91cd\u65b0\u6392\u7248\u5355\u8bcd\uff0c\u4f7f\u5176\u6210\u4e3a\u6bcf\u884c\u6070\u597d\u6709\u00a0maxWidth\u00a0\u4e2a\u5b57\u7b26\uff0c\u4e14\u5de6\u53f3\u4e24\u7aef\u5bf9\u9f50\u7684\u6587\u672c\u3002\n\n\u4f60\u5e94\u8be5\u4f7f\u7528 \u201c\u8d2a\u5fc3\u7b97\u6cd5\u201d \u6765\u653e\u7f6e\u7ed9\u5b9a\u7684\u5355\u8bcd\uff1b\u4e5f\u5c31\u662f\u8bf4\uff0c\u5c3d\u53ef\u80fd\u591a\u5730\u5f80\u6bcf\u884c\u4e2d\u653e\u7f6e\u5355\u8bcd\u3002\u5fc5\u8981\u65f6\u53ef\u7528\u7a7a\u683c\u00a0' '\u00a0\u586b\u5145\uff0c\u4f7f\u5f97\u6bcf\u884c\u6070\u597d\u6709 maxWidth\u00a0\u4e2a\u5b57\u7b26\u3002\n\n\u8981\u6c42\u5c3d\u53ef\u80fd\u5747\u5300\u5206\u914d\u5355\u8bcd\u95f4\u7684\u7a7a\u683c\u6570\u91cf\u3002\u5982\u679c\u67d0\u4e00\u884c\u5355\u8bcd\u95f4\u7684\u7a7a\u683c\u4e0d\u80fd\u5747\u5300\u5206\u914d\uff0c\u5219\u5de6\u4fa7\u653e\u7f6e\u7684\u7a7a\u683c\u6570\u8981\u591a\u4e8e\u53f3\u4fa7\u7684\u7a7a\u683c\u6570\u3002\n\n\u6587\u672c\u7684\u6700\u540e\u4e00\u884c\u5e94\u4e3a\u5de6\u5bf9\u9f50\uff0c\u4e14\u5355\u8bcd\u4e4b\u95f4\u4e0d\u63d2\u5165\u989d\u5916\u7684\u7a7a\u683c\u3002\n\n\u6ce8\u610f:\n\n\t\u5355\u8bcd\u662f\u6307\u7531\u975e\u7a7a\u683c\u5b57\u7b26\u7ec4\u6210\u7684\u5b57\u7b26\u5e8f\u5217\u3002\n\n\t\u6bcf\u4e2a\u5355\u8bcd\u7684\u957f\u5ea6\u5927\u4e8e 0\uff0c\u5c0f\u4e8e\u7b49\u4e8e\u00a0maxWidth\u3002\n\n\t\u8f93\u5165\u5355\u8bcd\u6570\u7ec4 words\u00a0\u81f3\u5c11\u5305\u542b\u4e00\u4e2a\u5355\u8bcd\u3002\n\n\u00a0\n\n\u793a\u4f8b 1:\n\n```\n\u8f93\u5165: words = [\"This\", \"is\", \"an\", \"example\", \"of\", \"text\", \"justification.\"], maxWidth = 16\n\u8f93\u51fa:\n[\n\u00a0 \u00a0\"This \u00a0 \u00a0is \u00a0 \u00a0an\",\n\u00a0 \u00a0\"example \u00a0of text\",\n\u00a0 \u00a0\"justification. \u00a0\"\n]\n```\n\n\u793a\u4f8b\u00a02:\n\n```\n\u8f93\u5165:words = [\"What\",\"must\",\"be\",\"acknowledgment\",\"shall\",\"be\"], maxWidth = 16\n\u8f93\u51fa:\n[\n\u00a0 \"What \u00a0 must \u00a0 be\",\n\u00a0 \"acknowledgment \u00a0\",\n\u00a0 \"shall be \u00a0 \u00a0 \u00a0 \u00a0\"\n]\n\u89e3\u91ca: \u6ce8\u610f\u6700\u540e\u4e00\u884c\u7684\u683c\u5f0f\u5e94\u4e3a \"shall be    \" \u800c\u4e0d\u662f \"shall     be\",\n\u00a0    \u56e0\u4e3a\u6700\u540e\u4e00\u884c\u5e94\u4e3a\u5de6\u5bf9\u9f50\uff0c\u800c\u4e0d\u662f\u5de6\u53f3\u4e24\u7aef\u5bf9\u9f50\u3002\n     \u7b2c\u4e8c\u884c\u540c\u6837\u4e3a\u5de6\u5bf9\u9f50\uff0c\u8fd9\u662f\u56e0\u4e3a\u8fd9\u884c\u53ea\u5305\u542b\u4e00\u4e2a\u5355\u8bcd\u3002\n```\n\n\u793a\u4f8b\u00a03:\n\n```\n\u8f93\u5165:words = [\"Science\",\"is\",\"what\",\"we\",\"understand\",\"well\",\"enough\",\"to\",\"explain\",\"to\",\"a\",\"computer.\",\"Art\",\"is\",\"everything\",\"else\",\"we\",\"do\"]\uff0cmaxWidth = 20\n\u8f93\u51fa:\n[\n\u00a0 \"Science \u00a0is \u00a0what we\",\n  \"understand \u00a0 \u00a0 \u00a0well\",\n\u00a0 \"enough to explain to\",\n\u00a0 \"a \u00a0computer. \u00a0Art is\",\n\u00a0 \"everything \u00a0else \u00a0we\",\n\u00a0 \"do \u00a0 \u00a0 \u00a0 \u00a0 \u00a0 \u00a0 \u00a0 \u00a0 \u00a0\"\n]\n```\n\n\u00a0\n\n\u63d0\u793a:\n\n\t1 <= words.length <= 300\n\n\t1 <= words[i].length <= 20\n\n\twords[i]\u00a0\u7531\u5c0f\u5199\u82f1\u6587\u5b57\u6bcd\u548c\u7b26\u53f7\u7ec4\u6210\n\n\t1 <= maxWidth <= 100\n\n\twords[i].length <= maxWidth",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1awords\u3001maxWidth\u3002",
    "\u8f93\u51fa list<string> \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\n# blank \u8fd4\u56de\u957f\u5ea6\u4e3a n \u7684\u7531\u7a7a\u683c\u7ec4\u6210\u7684\u5b57\u7b26\u4e32\ndef blank(n: int) -> str:\n    return ' ' * n\n\nclass Solution:\n    def fullJustify(self, words: List[str], maxWidth: int) -> List[str]:\n        ans = []\n        right, n = 0, len(words)\n        while True:\n            left = right  # \u5f53\u524d\u884c\u7684\u7b2c\u4e00\u4e2a\u5355\u8bcd\u5728 words \u7684\u4f4d\u7f6e\n            sumLen = 0  # \u7edf\u8ba1\u8fd9\u4e00\u884c\u5355\u8bcd\u957f\u5ea6\u4e4b\u548c\n            # \u5faa\u73af\u786e\u5b9a\u5f53\u524d\u884c\u53ef\u4ee5\u653e\u591a\u5c11\u5355\u8bcd\uff0c\u6ce8\u610f\u5355\u8bcd\u4e4b\u95f4\u5e94\u81f3\u5c11\u6709\u4e00\u4e2a\u7a7a\u683c\n            while right < n and sumLen + len(words[right]) + right - left <= maxWidth:\n                sumLen += len(words[right])\n                right += 1\n\n            # \u5f53\u524d\u884c\u662f\u6700\u540e\u4e00\u884c\uff1a\u5355\u8bcd\u5de6\u5bf9\u9f50\uff0c\u4e14\u5355\u8bcd\u4e4b\u95f4\u5e94\u53ea\u6709\u4e00\u4e2a\u7a7a\u683c\uff0c\u5728\u884c\u672b\u586b\u5145\u5269\u4f59\u7a7a\u683c\n            if right == n:\n                s = \" \".join(words[left:])\n                ans.append(s + blank(maxWidth - len(s)))\n                break\n\n            numWords = right - left\n            numSpaces = maxWidth - sumLen\n\n            # \u5f53\u524d\u884c\u53ea\u6709\u4e00\u4e2a\u5355\u8bcd\uff1a\u8be5\u5355\u8bcd\u5de6\u5bf9\u9f50\uff0c\u5728\u884c\u672b\u586b\u5145\u7a7a\u683c\n            if numWords == 1:\n                ans.append(words[left] + blank(numSpaces))\n                continue\n\n            # \u5f53\u524d\u884c\u4e0d\u53ea\u4e00\u4e2a\u5355\u8bcd\n            avgSpaces = numSpaces // (numWords - 1)\n            extraSpaces = numSpaces % (numWords - 1)\n            s1 = blank(avgSpaces + 1).join(words[left:left + extraSpaces + 1])  # \u62fc\u63a5\u989d\u5916\u52a0\u4e00\u4e2a\u7a7a\u683c\u7684\u5355\u8bcd\n            s2 = blank(avgSpaces).join(words[left + extraSpaces + 1:right])  # \u62fc\u63a5\u5176\u4f59\u5355\u8bcd\n            ans.append(s1 + blank(avgSpaces) + s2)\n\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.fullJustify(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
