    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass StreamChecker:\n\n    def __init__(self, words: List[str]):\n        self.root = TrieNode()\n        for word in words:\n            cur = self.root\n            for char in word:\n                idx = ord(char) - ord('a')\n                if not cur.children[idx]:\n                    cur.children[idx] = TrieNode()\n                cur = cur.children[idx]\n            cur.isEnd = True\n        \n        self.root.fail = self.root\n        q = deque()\n        for i in range(26):\n            if self.root.children[i]:\n                self.root.children[i].fail = self.root\n                q.append(self.root.children[i])\n            else:\n                self.root.children[i] = self.root\n        while q:\n            node = q.popleft()\n            node.isEnd = node.isEnd or node.fail.isEnd\n            for i in range(26):\n                if node.children[i]:\n                    node.children[i].fail = node.fail.children[i]\n                    q.append(node.children[i])\n                else:\n                    node.children[i] = node.fail.children[i]\n\n        self.temp = self.root\n            \n    def query(self, letter: str) -> bool:\n        self.temp = self.temp.children[ord(letter) - ord('a')]\n        return self.temp.isEnd\n\nclass TrieNode:\n    def __init__(self):\n        self.children = [None] * 26\n        self.isEnd = False\n        self.fail = None\n\ndef main():\n    _lines = [x for x in sys.stdin.read().split('\\n') if x.strip() != '']\n    _ops = json.loads(_lines[0])\n    _args = json.loads(_lines[1]) if len(_lines) > 1 else []\n    _obj = None\n    _out = []\n    for _i, _op in enumerate(_ops):\n        _a = _args[_i] if _i < len(_args) else []\n        if _i == 0:\n            _obj = StreamChecker(*_a)\n            _out.append(None)\n        else:\n            _out.append(getattr(_obj, _op)(*_a))\n    print(json.dumps(_out, separators=(',', ':')))\n\nmain()\n",
