    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def minCost(self, s: str, encCost: int, flatCost: int) -> int:\n        pre = [0]\n        for w in s:\n            pre.append(pre[-1])\n            if w == '1':\n                pre[-1] += 1\n        \n        def getCost(l,r):\n            X = pre[r+1] - pre[l]\n            if not X:\n                return flatCost               \n            return (r-l+1)*X*encCost\n         \n                \n        @cache\n        def dfs(l,r):\n            # \u5947\u6570\u957f\u5ea6\u4e0d\u80fd\u62c6\u5206\n            if (r - l + 1)&1:\n                return getCost(l,r)\n            \n            # \u5076\u6570\u957f\u5ea6\n            # \u4e0d\u62c6\n            A = getCost(l,r)\n            # \u62c6\n            m = (l+r)//2\n            B = dfs(l,m)+dfs(m+1,r)\n            return min(A,B)\n        \n        res = dfs(0,len(s)-1)\n        dfs.cache_clear()\n        \n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.minCost(_args[0], _args[1], _args[2])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
