    "hard",
    "\u5b57\u7b26\u4e32",
    "\u7ed9\u4f60\u4e24\u4e2a\u5b57\u7b26\u4e32\u00a0s \u548c\u00a0sub\u00a0\u3002\u540c\u65f6\u7ed9\u4f60\u4e00\u4e2a\u4e8c\u7ef4\u5b57\u7b26\u6570\u7ec4\u00a0mappings \uff0c\u5176\u4e2d\u00a0mappings[i] = [oldi, newi]\u00a0\u8868\u793a\u4f60\u53ef\u4ee5\u5c06\u00a0sub\u00a0\u4e2d\u4efb\u610f\u6570\u76ee\u7684\u00a0oldi\u00a0\u5b57\u7b26\u66ff\u6362\u4e3a\u00a0newi\u00a0\u3002sub\u00a0\u4e2d\u6bcf\u4e2a\u5b57\u7b26 \u4e0d\u80fd\u00a0\u88ab\u66ff\u6362\u8d85\u8fc7\u4e00\u6b21\u3002\n\n\u5982\u679c\u4f7f\u7528 mappings\u00a0\u66ff\u6362 0 \u4e2a\u6216\u8005\u82e5\u5e72\u4e2a\u5b57\u7b26\uff0c\u53ef\u4ee5\u5c06 sub\u00a0\u53d8\u6210 s\u00a0\u7684\u4e00\u4e2a\u5b50\u5b57\u7b26\u4e32\uff0c\u8bf7\u4f60\u8fd4\u56de\u00a0true\uff0c\u5426\u5219\u8fd4\u56de\u00a0false\u00a0\u3002\n\n\u4e00\u4e2a \u5b50\u5b57\u7b26\u4e32\u00a0\u662f\u5b57\u7b26\u4e32\u4e2d\u8fde\u7eed\u975e\u7a7a\u7684\u5b57\u7b26\u5e8f\u5217\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1as = \"fool3e7bar\", sub = \"leet\", mappings = [[\"e\",\"3\"],[\"t\",\"7\"],[\"t\",\"8\"]]\n\u8f93\u51fa\uff1atrue\n\u89e3\u91ca\uff1a\u5c06 sub \u4e2d\u7b2c\u4e00\u4e2a 'e' \u7528 '3' \u66ff\u6362\uff0c\u5c06 't' \u7528 '7' \u66ff\u6362\u3002\n\u73b0\u5728 sub = \"l3e7\" \uff0c\u5b83\u662f s \u7684\u5b50\u5b57\u7b26\u4e32\uff0c\u6240\u4ee5\u6211\u4eec\u8fd4\u56de true \u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1as = \"fooleetbar\", sub = \"f00l\", mappings = [[\"o\",\"0\"]]\n\u8f93\u51fa\uff1afalse\n\u89e3\u91ca\uff1a\u5b57\u7b26\u4e32 \"f00l\" \u4e0d\u662f s \u7684\u5b50\u4e32\u4e14\u6ca1\u6709\u53ef\u4ee5\u8fdb\u884c\u7684\u4fee\u6539\u3002\n\u6ce8\u610f\u6211\u4eec\u4e0d\u80fd\u7528 'o' \u66ff\u6362 '0' \u3002\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1as = \"Fool33tbaR\", sub = \"leetd\", mappings = [[\"e\",\"3\"],[\"t\",\"7\"],[\"t\",\"8\"],[\"d\",\"b\"],[\"p\",\"b\"]]\n\u8f93\u51fa\uff1atrue\n\u89e3\u91ca\uff1a\u5c06 sub \u91cc\u7b2c\u4e00\u4e2a\u548c\u7b2c\u4e8c\u4e2a 'e' \u7528 '3' \u66ff\u6362\uff0c\u7528 'b' \u66ff\u6362 sub \u91cc\u7684 'd' \u3002\n\u5f97\u5230 sub = \"l33tb\" \uff0c\u5b83\u662f s \u7684\u5b50\u5b57\u7b26\u4e32\uff0c\u6240\u4ee5\u6211\u4eec\u8fd4\u56de true \u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= sub.length <= s.length <= 5000\n\n\t0 <= mappings.length <= 1000\n\n\tmappings[i].length == 2\n\n\toldi != newi\n\n\ts \u548c\u00a0sub\u00a0\u53ea\u5305\u542b\u5927\u5199\u548c\u5c0f\u5199\u82f1\u6587\u5b57\u6bcd\u548c\u6570\u5b57\u3002\n\n\toldi \u548c\u00a0newi\u00a0\u662f\u5927\u5199\u3001\u5c0f\u5199\u5b57\u6bcd\u6216\u8005\u662f\u4e2a\u6570\u5b57\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1as\u3001sub\u3001mappings\u3002",
    "\u8f93\u51fa boolean \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\r\n    def matchReplacement(self, s: str, sub: str, mappings: List[List[str]]) -> bool:\r\n        old = [0]*128\r\n        new = [0]*128\r\n        for i, c in enumerate(s):\r\n            new[ord(c)] |= 1 << i\r\n        for i in range(128):\r\n            old[i] |= new[i]\r\n        for c1, c2 in mappings:\r\n            old[ord(c1)] |= new[ord(c2)]\r\n        ans = old[ord(sub[0])]\r\n        for i, c in enumerate(sub):\r\n            ans &= old[ord(c)] >> i\r\n        return ans > 0\r\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.matchReplacement(_args[0], _args[1], _args[2])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
