    "\u5b57\u7b26\u4e32",
    "\u7ed9\u4f60\u4e24\u4e2a\u5b57\u7b26\u4e32\u6570\u7ec4\u00a0wordsContainer \u548c\u00a0wordsQuery\u00a0\u3002\n\n\u5bf9\u4e8e\u6bcf\u4e2a\u00a0wordsQuery[i]\u00a0\uff0c\u4f60\u9700\u8981\u4ece\u00a0wordsContainer\u00a0\u4e2d\u627e\u5230\u4e00\u4e2a\u4e0e\u00a0wordsQuery[i]\u00a0\u6709\u00a0\u6700\u957f\u516c\u5171\u540e\u7f00\u00a0\u7684\u5b57\u7b26\u4e32\u3002\u5982\u679c wordsContainer\u00a0\u4e2d\u6709\u4e24\u4e2a\u6216\u8005\u66f4\u591a\u5b57\u7b26\u4e32\u6709\u6700\u957f\u516c\u5171\u540e\u7f00\uff0c\u90a3\u4e48\u7b54\u6848\u4e3a\u957f\u5ea6\u00a0\u6700\u77ed\u00a0\u7684\u3002\u5982\u679c\u6709\u8d85\u8fc7\u4e24\u4e2a\u5b57\u7b26\u4e32\u6709\u00a0\u76f8\u540c\u00a0\u6700\u77ed\u957f\u5ea6\uff0c\u90a3\u4e48\u7b54\u6848\u4e3a\u5b83\u4eec\u5728\u00a0wordsContainer\u00a0\u4e2d\u51fa\u73b0\u00a0\u66f4\u65e9\u00a0\u7684\u4e00\u4e2a\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u4e00\u4e2a\u6574\u6570\u6570\u7ec4\u00a0ans\u00a0\uff0c\u5176\u4e2d\u00a0ans[i]\u662f\u00a0wordsContainer\u4e2d\u4e0e\u00a0wordsQuery[i]\u00a0\u6709\u00a0\u6700\u957f\u516c\u5171\u540e\u7f00\u00a0\u5b57\u7b26\u4e32\u7684\u4e0b\u6807\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n\u8f93\u5165\uff1awordsContainer = [\"abcd\",\"bcd\",\"xbcd\"], wordsQuery = [\"cd\",\"bcd\",\"xyz\"]\n\n\u8f93\u51fa\uff1a[1,1,1]\n\n\u89e3\u91ca\uff1a\n\n\u6211\u4eec\u5206\u522b\u6765\u770b\u6bcf\u4e00\u4e2a\u00a0wordsQuery[i]\u00a0\uff1a\n\n\t\u5bf9\u4e8e\u00a0wordsQuery[0] = \"cd\"\u00a0\uff0cwordsContainer\u00a0\u4e2d\u6709\u6700\u957f\u516c\u5171\u540e\u7f00\u00a0\"cd\"\u00a0\u7684\u5b57\u7b26\u4e32\u4e0b\u6807\u5206\u522b\u4e3a\u00a00 \uff0c1 \u548c\u00a02 \u3002\u8fd9\u4e9b\u5b57\u7b26\u4e32\u4e2d\uff0c\u7b54\u6848\u662f\u4e0b\u6807\u4e3a 1 \u7684\u5b57\u7b26\u4e32\uff0c\u56e0\u4e3a\u5b83\u7684\u957f\u5ea6\u4e3a 3 \uff0c\u662f\u6700\u77ed\u7684\u5b57\u7b26\u4e32\u3002\n\n\t\u5bf9\u4e8e\u00a0wordsQuery[1] = \"bcd\"\u00a0\uff0cwordsContainer\u00a0\u4e2d\u6709\u6700\u957f\u516c\u5171\u540e\u7f00\u00a0\"bcd\"\u00a0\u7684\u5b57\u7b26\u4e32\u4e0b\u6807\u5206\u522b\u4e3a 0 \uff0c1 \u548c 2 \u3002\u8fd9\u4e9b\u5b57\u7b26\u4e32\u4e2d\uff0c\u7b54\u6848\u662f\u4e0b\u6807\u4e3a 1 \u7684\u5b57\u7b26\u4e32\uff0c\u56e0\u4e3a\u5b83\u7684\u957f\u5ea6\u4e3a 3 \uff0c\u662f\u6700\u77ed\u7684\u5b57\u7b26\u4e32\u3002\n\n\t\u5bf9\u4e8e\u00a0wordsQuery[2] = \"xyz\"\u00a0\uff0cwordsContainer\u00a0\u4e2d\u6ca1\u6709\u5b57\u7b26\u4e32\u8ddf\u5b83\u6709\u516c\u5171\u540e\u7f00\uff0c\u6240\u4ee5\u6700\u957f\u516c\u5171\u540e\u7f00\u4e3a\u00a0\"\"\u00a0\uff0c\u4e0b\u6807\u4e3a\u00a00 \uff0c1 \u548c 2 \u7684\u5b57\u7b26\u4e32\u90fd\u5f97\u5230\u8fd9\u4e00\u516c\u5171\u540e\u7f00\u3002\u8fd9\u4e9b\u5b57\u7b26\u4e32\u4e2d\uff0c\u00a0\u7b54\u6848\u662f\u4e0b\u6807\u4e3a 1 \u7684\u5b57\u7b26\u4e32\uff0c\u56e0\u4e3a\u5b83\u7684\u957f\u5ea6\u4e3a 3 \uff0c\u662f\u6700\u77ed\u7684\u5b57\u7b26\u4e32\u3002\n\n\u793a\u4f8b 2\uff1a\n\n\u8f93\u5165\uff1awordsContainer = [\"abcdefgh\",\"poiuygh\",\"ghghgh\"], wordsQuery = [\"gh\",\"acbfgh\",\"acbfegh\"]\n\n\u8f93\u51fa\uff1a[2,0,2]\n\n\u89e3\u91ca\uff1a\n\n\u6211\u4eec\u5206\u522b\u6765\u770b\u6bcf\u4e00\u4e2a\u00a0wordsQuery[i]\u00a0\uff1a\n\n\t\u5bf9\u4e8e\u00a0wordsQuery[0] = \"gh\"\u00a0\uff0cwordsContainer\u00a0\u4e2d\u6709\u6700\u957f\u516c\u5171\u540e\u7f00\u00a0\"gh\"\u00a0\u7684\u5b57\u7b26\u4e32\u4e0b\u6807\u5206\u522b\u4e3a 0 \uff0c1 \u548c 2 \u3002\u8fd9\u4e9b\u5b57\u7b26\u4e32\u4e2d\uff0c\u7b54\u6848\u662f\u4e0b\u6807\u4e3a 2 \u7684\u5b57\u7b26\u4e32\uff0c\u56e0\u4e3a\u5b83\u7684\u957f\u5ea6\u4e3a 6 \uff0c\u662f\u6700\u77ed\u7684\u5b57\u7b26\u4e32\u3002\n\n\t\u5bf9\u4e8e\u00a0wordsQuery[1] = \"acbfgh\"\u00a0\uff0c\u53ea\u6709\u4e0b\u6807\u4e3a 0 \u7684\u5b57\u7b26\u4e32\u6709\u6700\u957f\u516c\u5171\u540e\u7f00\u00a0\"fgh\"\u00a0\u3002\u6240\u4ee5\u5c3d\u7ba1\u4e0b\u6807\u4e3a 2 \u7684\u5b57\u7b26\u4e32\u662f\u6700\u77ed\u7684\u5b57\u7b26\u4e32\uff0c\u4f46\u7b54\u6848\u662f 0 \u3002\n\n\t\u5bf9\u4e8e\u00a0wordsQuery[2] = \"acbfegh\"\u00a0\uff0cwordsContainer\u00a0\u4e2d\u6709\u6700\u957f\u516c\u5171\u540e\u7f00\u00a0\"gh\"\u00a0\u7684\u5b57\u7b26\u4e32\u4e0b\u6807\u5206\u522b\u4e3a 0 \uff0c1 \u548c 2 \u3002\u8fd9\u4e9b\u5b57\u7b26\u4e32\u4e2d\uff0c\u7b54\u6848\u662f\u4e0b\u6807\u4e3a 2 \u7684\u5b57\u7b26\u4e32\uff0c\u56e0\u4e3a\u5b83\u7684\u957f\u5ea6\u4e3a 6 \uff0c\u662f\u6700\u77ed\u7684\u5b57\u7b26\u4e32\u3002\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= wordsContainer.length, wordsQuery.length <= 104\n\n\t1 <= wordsContainer[i].length <= 5 * 103\n\n\t1 <= wordsQuery[i].length <= 5 * 103\n\n\twordsContainer[i]\u00a0\u53ea\u5305\u542b\u5c0f\u5199\u82f1\u6587\u5b57\u6bcd\u3002\n\n\twordsQuery[i]\u00a0\u53ea\u5305\u542b\u5c0f\u5199\u82f1\u6587\u5b57\u6bcd\u3002\n\n\twordsContainer[i].length\u00a0\u7684\u548c\u81f3\u591a\u4e3a\u00a05 * 105\u00a0\u3002\n\n\twordsQuery[i].length\u00a0\u7684\u548c\u81f3\u591a\u4e3a\u00a05 * 105\u00a0\u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1awordsContainer\u3001wordsQuery\u3002",
    "\u8f93\u51fa integer[] \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass TrieNode:\n    def __init__(self):\n        self.children = {}\n        self.min_len = float('inf')\n        self.idx = float('inf')\n\n\nclass Trie:\n    def __init__(self):\n        self.root = TrieNode()\n    \n    def insert(self, s: str, idx: int):\n        node = self.root\n        if len(s) < node.min_len:\n            node.min_len = len(s)\n            node.idx = idx\n        \n        for ch in s:\n            c = ch\n            if c not in node.children:\n                node.children[c] = TrieNode()\n            node = node.children[c]\n            \n            if len(s) < node.min_len:\n                node.min_len = len(s)\n                node.idx = idx\n    \n    def query(self, s: str) -> int:\n        node = self.root\n        \n        for ch in s:\n            if ch in node.children:\n                node = node.children[ch]\n            else:\n                break\n        \n        return node.idx\n\n\nclass Solution:\n    def stringIndices(self, wordsContainer: List[str], wordsQuery: List[str]) -> List[int]:\n        trie = Trie()\n        \n        for i, word in enumerate(wordsContainer):\n            reversed_word = word[::-1]\n            trie.insert(reversed_word, i)\n        \n        res = []\n        for query in wordsQuery:\n            reversed_query = query[::-1]\n            res.append(trie.query(reversed_query))\n        \n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.stringIndices(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
