    "\u7ed9\u5b9a\u4e24\u4e2a\u5b57\u7b26\u4e32\u00a0s\u00a0\u548c\u00a0t\u00a0\uff0c\u6bcf\u4e2a\u5b57\u7b26\u4e32\u4ee3\u8868\u4e00\u4e2a\u975e\u8d1f\u6709\u7406\u6570\uff0c\u53ea\u6709\u5f53\u5b83\u4eec\u8868\u793a\u76f8\u540c\u7684\u6570\u5b57\u65f6\u624d\u8fd4\u56de true\u00a0\u3002\u5b57\u7b26\u4e32\u4e2d\u53ef\u4ee5\u4f7f\u7528\u62ec\u53f7\u6765\u8868\u793a\u6709\u7406\u6570\u7684\u91cd\u590d\u90e8\u5206\u3002\n\n\u6709\u7406\u6570\u00a0\u6700\u591a\u53ef\u4ee5\u7528\u4e09\u4e2a\u90e8\u5206\u6765\u8868\u793a\uff1a\u6574\u6570\u90e8\u5206\u00a0<IntegerPart>\u3001\u5c0f\u6570\u975e\u91cd\u590d\u90e8\u5206\u00a0<NonRepeatingPart>\u00a0\u548c\u5c0f\u6570\u91cd\u590d\u90e8\u5206\u00a0<(><RepeatingPart><)>\u3002\u6570\u5b57\u53ef\u4ee5\u7528\u4ee5\u4e0b\u4e09\u79cd\u65b9\u6cd5\u4e4b\u4e00\u6765\u8868\u793a\uff1a\n\n\t<IntegerPart>\u00a0\n\n\t\t\u4f8b\uff1a\u00a00\u00a0,12\u00a0\u548c\u00a0123\u00a0\n\n\t<IntegerPart><.><NonRepeatingPart>\n\n\t\t\u4f8b\uff1a 0.5\u00a0, 1.\u00a0,\u00a02.12\u00a0\u548c\u00a0123.0001\n\n\t<IntegerPart><.><NonRepeatingPart><(><RepeatingPart><)>\u00a0\n\n\t\t\u4f8b\uff1a 0.1(6) \uff0c 1.(9)\uff0c 123.00(1212)\n\n\u5341\u8fdb\u5236\u5c55\u5f00\u7684\u91cd\u590d\u90e8\u5206\u901a\u5e38\u5728\u4e00\u5bf9\u5706\u62ec\u53f7\u5185\u8868\u793a\u3002\u4f8b\u5982\uff1a\n\n\t1 / 6 = 0.16666666... = 0.1(6) = 0.1666(6) = 0.166(66)\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1as = \"0.(52)\", t = \"0.5(25)\"\n\u8f93\u51fa\uff1atrue\n\u89e3\u91ca\uff1a\u56e0\u4e3a \"0.(52)\" \u4ee3\u8868 0.52525252...\uff0c\u800c \"0.5(25)\" \u4ee3\u8868 0.52525252525.....\uff0c\u5219\u8fd9\u4e24\u4e2a\u5b57\u7b26\u4e32\u8868\u793a\u76f8\u540c\u7684\u6570\u5b57\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1as = \"0.1666(6)\", t = \"0.166(66)\"\n\u8f93\u51fa\uff1atrue\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1as = \"0.9(9)\", t = \"1.\"\n\u8f93\u51fa\uff1atrue\n\u89e3\u91ca\uff1a\"0.9(9)\" \u4ee3\u8868 0.999999999... \u6c38\u8fdc\u91cd\u590d\uff0c\u7b49\u4e8e 1 \u3002[\u6709\u5173\u8bf4\u660e\uff0c\u8bf7\u53c2\u9605\u6b64\u94fe\u63a5]\n\"1.\" \u8868\u793a\u6570\u5b57 1\uff0c\u5176\u683c\u5f0f\u6b63\u786e\uff1a(IntegerPart) = \"1\" \u4e14 (NonRepeatingPart) = \"\" \u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t\u6bcf\u4e2a\u90e8\u5206\u4ec5\u7531\u6570\u5b57\u7ec4\u6210\u3002\n\n\t\u6574\u6570\u90e8\u5206\u00a0<IntegerPart>\u00a0\u4e0d\u4f1a\u4ee5\u96f6\u5f00\u5934\u3002\uff08\u96f6\u672c\u8eab\u9664\u5916\uff09\n\n\t1 <= <IntegerPart>.length <= 4\n\n\t0 <= <NonRepeatingPart>.length <= 4\n\n\t1 <= <RepeatingPart>.length <= 4\n\n\u200b\u200b\u200b\u200b\u200b",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1as\u3001t\u3002",
    "\u8f93\u51fa boolean \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nfrom fractions import Fraction\n\nclass Solution(object):\n    def isRationalEqual(self, S, T):\n        def convert(S):\n            if '.' not in S:\n                return Fraction(int(S), 1)\n            i = S.index('.')\n            ans = Fraction(int(S[:i]), 1)\n            S = S[i+1:]\n            if '(' not in S:\n                if S:\n                    ans += Fraction(int(S), 10 ** len(S))\n                return ans\n\n            i = S.index('(')\n            if i:\n                ans += Fraction(int(S[:i]), 10 ** i)\n            S = S[i+1:-1]\n            j = len(S)\n            ans += Fraction(int(S), 10**i * (10**j - 1))\n            return ans\n\n        return convert(S) == convert(T)\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.isRationalEqual(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
