    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\nclass WordFilter:\n\n    def __init__(self, words: List[str]):\n        self.d = {}\n        for i, word in enumerate(words):\n            m = len(word)\n            for prefixLength in range(1, m + 1):\n                for suffixLength in range(1, m + 1):\n                    self.d[word[:prefixLength] + '#' + word[-suffixLength:]] = i\n\n\n    def f(self, pref: str, suff: str) -> int:\n        return self.d.get(pref + '#' + suff, -1)\n\ndef main():\n    _lines = [x for x in sys.stdin.read().split('\\n') if x.strip() != '']\n    _ops = json.loads(_lines[0])\n    _args = json.loads(_lines[1]) if len(_lines) > 1 else []\n    _obj = None\n    _out = []\n    for _i, _op in enumerate(_ops):\n        _a = _args[_i] if _i < len(_args) else []\n        if _i == 0:\n            _obj = WordFilter(*_a)\n            _out.append(None)\n        else:\n            _out.append(getattr(_obj, _op)(*_a))\n    print(json.dumps(_out, separators=(',', ':')))\n\nmain()\n",
    "token_list",
    [["[\"WordFilter\",\"f\"]\n[[[\"apple\"]],[\"a\",\"e\"]]", "[null,0]"]],
