PSH14 = mk(
    "SH14",
    "\u5b57\u5178\u5e8f\u7684\u7b2cK\u5c0f\u6570\u5b57",
    "LeetCode 440",
    "hard",
    "\u5b57\u7b26\u4e32",
    "\u7ed9\u5b9a\u6574\u6570\u00a0n\u00a0\u548c\u00a0k\uff0c\u8fd4\u56de\u00a0\u00a0[1, n]\u00a0\u4e2d\u5b57\u5178\u5e8f\u7b2c\u00a0k\u00a0\u5c0f\u7684\u6570\u5b57\u3002\n\n\u00a0\n\n\u793a\u4f8b 1:\n\n```\n\u8f93\u5165: n = 13, k = 2\n\u8f93\u51fa: 10\n\u89e3\u91ca: \u5b57\u5178\u5e8f\u7684\u6392\u5217\u662f [1, 10, 11, 12, 13, 2, 3, 4, 5, 6, 7, 8, 9]\uff0c\u6240\u4ee5\u7b2c\u4e8c\u5c0f\u7684\u6570\u5b57\u662f 10\u3002\n```\n\n\u793a\u4f8b 2:\n\n```\n\u8f93\u5165: n = 1, k = 1\n\u8f93\u51fa: 1\n```\n\n\u00a0\n\n\u63d0\u793a:\n\n\t1 <= k <= n <= 109",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1an\u3001k\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def getSteps(self, cur: int, n: int) -> int:\n        steps, first, last = 0, cur, cur\n        while first <= n:\n            steps += min(last, n) - first + 1\n            first *= 10\n            last = last * 10 + 9\n        return steps\n\n    def findKthNumber(self, n: int, k: int) -> int:\n        cur = 1\n        k -= 1\n        while k:\n            steps = self.getSteps(cur, n)\n            if steps <= k:\n                k -= steps\n                cur += 1\n            else:\n                cur *= 10\n                k -= 1\n        return cur\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.findKthNumber(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "int",
    [["13\n2", "10"], ["1\n1", "1"]],
    ["trie", "\u5b57\u7b26\u4e32"],
    )
